fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Given 1-based index k, and assumption 1 <= k < list.len()
    // we want to remove the element at position k (1-based),
    // so in 0-based indexing, the removed element is at index k-1.
    
    let n = list.len();
    // Allocate a vector with capacity n-1 to avoid reallocations.
    let mut new_list = Vec::with_capacity(n - 1);

    // Push elements before the removed element (indices 0 to k-2).
    new_list.extend_from_slice(&list[0..k-1]);

    // Push elements after the removed element (indices k to n-1).
    new_list.extend_from_slice(&list[k..n]);

    new_list
}